import base64

clean_block_b64 = b''

with open('index.html', 'r', encoding='utf-8') as f:
    lines = f.readlines()

clean_block = base64.b64decode(clean_block_b64).decode('utf-8')

# Find 8164 block to delete
start_8164 = -1
end_8164 = -1
for i in range(8000, 8300):
    if "const meetingLog = document.getElementById('ai-meeting-log');" in lines[i]:
        start_8164 = i
        for j in range(start_8164, len(lines)):
            if "eqGrowthEl.innerText =" in lines[j]:
                end_8164 = j - 1
                while "}" not in lines[end_8164]:
                    end_8164 -= 1
                end_8164 += 1
                break
        break

# Find 8745 block to replace
start_8745 = -1
end_8745 = -1
for i in range(8600, 8800):
    if "const meetingLog = document.getElementById('ai-meeting-log');" in lines[i] and i > start_8164 + 10:
        start_8745 = i
        for j in range(start_8745, len(lines)):
            if "meetingLog.scrollTop = meetingLog.scrollHeight;" in lines[j]:
                end_8745 = j + 1
                while "}" not in lines[end_8745]:
                    end_8745 += 1
                end_8745 += 1
                break
        break

if start_8164 != -1 and start_8745 != -1:
    new_lines = lines[:start_8164] + lines[end_8164:start_8745] + [clean_block + "\\n"] + lines[end_8745:]
    with open('index.html', 'w', encoding='utf-8') as f:
        f.writelines(new_lines)
    print("Patched completely!")
else:
    print(f"Blocks not found! {start_8164} {end_8164} {start_8745} {end_8745}")
